// ArcadeHub: stands in for the GameDistribution ad SDK (html5.api.gamedistribution.com/main.min.js).
// The original copy had the real SDK here; it contacts GameDistribution and ad networks.
// This version fetches nothing and shows no ads. The game only needs the "SDK_READY"
// event and a gdsdk object; its own ad check (js/null.js) already turns ads off.
(function () {
  window.gdsdk = {
    showAd: function () { return Promise.resolve(); },
    preloadAd: function () { return Promise.reject(new Error('no ads')); },
    cancelAd: function () { return Promise.resolve(); },
    openConsole: function () {}
  };
  setTimeout(function () {
    var options = window.GD_OPTIONS;
    if (options && typeof options.onEvent === 'function') options.onEvent({ name: 'SDK_READY' });
  }, 0);
})();
